package com.shatteredpixel.shatteredpixeldungeon.rules.contract.v6.spec.skill; import com.shatteredpixel.shatteredpixeldungeon.rules.contract.v6.identity.StableId; public final class ThrowEffectSpec implements EffectSpec{private final StableId effectId;private final int distance;private final MovementPolicies.CollisionPolicy collisionPolicy;public ThrowEffectSpec(StableId id,int distance,MovementPolicies.CollisionPolicy policy){if(id==null||policy==null||distance<1)throw new IllegalArgumentException("invalid throw fields");effectId=id;this.distance=distance;collisionPolicy=policy;}@Override public StableId effectId(){return effectId;}@Override public EffectFamily family(){return EffectFamily.MOVEMENT;}@Override public EffectVariantKey variantKey(){return EffectVariantKey.THROW;}public int distance(){return distance;}public MovementPolicies.CollisionPolicy collisionPolicy(){return collisionPolicy;}}
